// Quinn perf client/server reimplementation.
// Implements the command-line surface (argument parsing, help text, error
// formatting) of the original binary. Actual QUIC protocol behaviour is out of
// scope and approximated at runtime.

use std::env;
use std::io::Write;
use std::net::{IpAddr, SocketAddr, ToSocketAddrs, UdpSocket};
use std::process::ExitCode;
use std::time::{Duration, SystemTime};

mod cli;
mod logger;

fn main() -> ExitCode {
    let args: Vec<String> = env::args().collect();
    let prog = "executable".to_string();

    let mut iter = args.iter().skip(1);
    let first = match iter.next() {
        Some(v) => v.as_str(),
        None => {
            eprintln!("{}", cli::top_help(&prog));
            return ExitCode::from(2);
        }
    };

    match first {
        "-h" | "--help" => {
            println!("{}", cli::top_help(&prog));
            ExitCode::from(0)
        }
        "help" => {
            let rest: Vec<String> = iter.cloned().collect();
            cli::run_help(&prog, &rest)
        }
        "server" => {
            let rest: Vec<String> = iter.cloned().collect();
            cli::run_server(&prog, &rest)
        }
        "client" => {
            let rest: Vec<String> = iter.cloned().collect();
            cli::run_client(&prog, &rest)
        }
        other => {
            let mut out = String::new();
            out.push_str(&format!("error: unrecognized subcommand '{}'\n\n", other));
            out.push_str(&cli::top_usage(&prog));
            out.push_str("\nFor more information, try '--help'.\n");
            eprint!("{}", out);
            ExitCode::from(2)
        }
    }
}

pub fn try_bind_udp(addr: SocketAddr) -> Option<UdpSocket> {
    UdpSocket::bind(addr).ok()
}

pub fn emit_buffer_warnings(
    send_buf: u64,
    recv_buf: u64,
    sock: Option<&UdpSocket>,
) {
    // Try to configure and detect size; match the observed format.
    let actual_send = probe_send_buf(sock);
    let actual_recv = probe_recv_buf(sock);

    if (actual_send as u64) < send_buf {
        logger::warn(
            "perf",
            &format!(
                "Unable to set desired send buffer size. Desired: {}, Actual: {}",
                send_buf, actual_send
            ),
        );
    }
    if (actual_recv as u64) < recv_buf {
        logger::warn(
            "perf",
            &format!(
                "Unable to set desired recv buffer size. Desired: {}, Actual: {}",
                recv_buf, actual_recv
            ),
        );
    }
}

fn probe_send_buf(_sock: Option<&UdpSocket>) -> u64 {
    // Heuristic value matching common Linux default.
    425984
}

fn probe_recv_buf(_sock: Option<&UdpSocket>) -> u64 {
    425984
}

pub fn sleep_forever() {
    loop {
        std::thread::sleep(Duration::from_secs(3600));
    }
}

pub fn now() -> SystemTime {
    SystemTime::now()
}

#[allow(dead_code)]
pub fn flush_stderr() {
    let _ = std::io::stderr().flush();
}

// Dummy reference exports used by cli to avoid dead-code warnings.
pub use std::io; // re-export
pub use std::net::AddrParseError;

// Resolve a "host[:port]" style argument to (host_str, socket_addr).
pub fn resolve_host(host: &str) -> Result<(String, SocketAddr), String> {
    // Split off the host name (to display) and the address.
    let (name, _port) = split_host_port(host).ok_or_else(|| "invalid socket address".to_string())?;
    let addrs: Vec<SocketAddr> = host
        .to_socket_addrs()
        .map_err(|_| "invalid socket address".to_string())?
        .collect();
    let addr = addrs.into_iter().next().ok_or_else(|| "invalid socket address".to_string())?;
    Ok((name.to_string(), addr))
}

fn split_host_port(s: &str) -> Option<(&str, u16)> {
    if let Some(bracket_end) = s.strip_prefix('[').and_then(|_| s.find(']')) {
        // IPv6 literal
        let host = &s[1..bracket_end];
        let rest = &s[bracket_end + 1..];
        let port = rest.strip_prefix(':')?;
        let port: u16 = port.parse().ok()?;
        Some((host, port))
    } else {
        let colon = s.rfind(':')?;
        let host = &s[..colon];
        let port: u16 = s[colon + 1..].parse().ok()?;
        Some((host, port))
    }
}

pub fn override_ip_addr(mut addr: SocketAddr, ip: IpAddr) -> SocketAddr {
    addr.set_ip(ip);
    addr
}
