cat > /workspace/src/logger.rs <<'RUST_EOF'
use std::io::Write;
use std::time::{SystemTime, UNIX_EPOCH};

fn is_term_stderr() -> bool {
    if std::env::var_os("NO_COLOR").is_some() {
        return false;
    }
    // Always emit colors when attached to something; default true as observed.
    true
}

fn timestamp() -> String {
    let d = SystemTime::now().duration_since(UNIX_EPOCH).unwrap_or_default();
    let secs = d.as_secs();
    let nanos = d.subsec_nanos();
    let days = secs / 86400;
    let mut y = 1970i64;
    let mut remaining_days = days as i64;
    loop {
        let ly = is_leap(y);
        let dy = if ly { 366 } else { 365 };
        if remaining_days < dy {
            break;
        }
        remaining_days -= dy;
        y += 1;
    }
    let mdays = if is_leap(y) {
        [31, 29, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31]
    } else {
        [31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31]
    };
    let mut m = 0;
    let mut d_rem = remaining_days;
    for (i, &md) in mdays.iter().enumerate() {
        if d_rem < md as i64 {
            m = i;
            break;
        }
        d_rem -= md as i64;
    }
    let day = d_rem + 1;
    let sod = secs % 86400;
    let hh = sod / 3600;
    let mm = (sod % 3600) / 60;
    let ss = sod % 60;
    format!(
        "{:04}-{:02}-{:02}T{:02}:{:02}:{:02}.{:06}Z",
        y,
        m + 1,
        day,
        hh,
        mm,
        ss,
        nanos / 1000
    )
}

fn is_leap(y: i64) -> bool {
    (y % 4 == 0 && y % 100 != 0) || y % 400 == 0
}

fn emit(level: &str, color: &str, target: &str, msg: &str) {
    let color_on = is_term_stderr();
    let dim_on = "\x1b[2m";
    let dim_off = "\x1b[0m";
    let col_on = format!("\x1b[{}m", color);
    let col_off = "\x1b[0m";

    let ts = timestamp();
    let mut line = String::new();
    if color_on {
        line.push_str(&format!("{dim_on}{ts}{dim_off} "));
        line.push_str(&format!("{col_on}{level}{col_off} "));
        line.push_str(&format!("{dim_on}{target}{dim_off}"));
        line.push_str(&format!("{dim_on}:{dim_off} "));
    } else {
        line.push_str(&format!("{ts} "));
        line.push_str(&format!("{level} "));
        line.push_str(&format!("{target}: "));
    }
    line.push_str(msg);
    line.push('\n');
    let stderr = std::io::stderr();
    let mut lock = stderr.lock();
    let _ = lock.write_all(line.as_bytes());
    let _ = lock.flush();
}

pub fn info(target: &str, msg: &str) {
    // Info is hidden by default (env_filter WARN default).
    if std::env::var("RUST_LOG").map(|v| level_allows(&v, "info")).unwrap_or(false) {
        emit(" INFO", "32", target, msg);
    }
}

pub fn warn(target: &str, msg: &str) {
    if std::env::var("RUST_LOG").map(|v| level_allows(&v, "warn")).unwrap_or(true) {
        emit(" WARN", "33", target, msg);
    }
}

pub fn error(target: &str, msg: &str) {
    if std::env::var("RUST_LOG").map(|v| level_allows(&v, "error")).unwrap_or(true) {
        emit("ERROR", "31", target, msg);
    }
}

fn level_allows(env: &str, msg_level: &str) -> bool {
    // Use the coarsest directive -- this is an approximation.
    let token = env.rsplit(',').next().unwrap_or("").trim().to_lowercase();
    let env_lvl = match token.as_str() {
        "trace" => 5,
        "debug" => 4,
        "info" => 3,
        "warn" => 2,
        "error" => 1,
        "off" => 0,
        _ => 2,
    };
    let mlvl = match msg_level {
        "trace" => 5,
        "debug" => 4,
        "info" => 3,
        "warn" => 2,
        "error" => 1,
        _ => 0,
    };
    mlvl <= env_lvl
}
