) -> String {
    let mut s = String::new();
    s.push_str(about);
    s.push_str("\n\n");
    if positional.is_some() {
        s.push_str(&format!("Usage: {} {} [OPTIONS] [HOST]\n", prog, name));
    } else {
        s.push_str(&format!("Usage: {} {} [OPTIONS]\n", prog, name));
