// Formatting help for the subcommand.
pub fn server_short_help(prog: &str) -> String { render_cmd_help(prog, "server", "Run as a perf server", &server_opts(), None, false) }
pub fn server_long_help(prog: &str)  -> String { render_cmd_help(prog, "server", "Run as a perf server", &server_opts(), None, true) }
pub fn client_short_help(prog: &str) -> String {
    render_cmd_help(prog, "client", "Run as a perf client", &client_opts(),
        Some(("HOST", "Host to connect to", "localhost:4433")), false)
}
pub fn client_long_help(prog: &str) -> String {
    render_cmd_help(prog, "client", "Run as a perf client", &client_opts(),
        Some(("HOST", "Host to connect to", "localhost:4433")), true)
}

fn render_cmd_help(
    prog: &str,
    name: &str,
    about: &str,
    opts: &[OptSpec],
    positional: Option<(&str, &str, &str)>,
    long: bool,
) -> String {
    let mut s = String::new();
    s.push_str(about);
    s.push_str("\n\n");
    if positional.is_some() {
        s.push_str(&format!("Usage: {} {} [OPTIONS] [HOST]\n", prog, name));
    } else {
        s.push_str(&format!("Usage: {} {} [OPTIONS]\n", prog, name));
    }
    s.push('\n');
    if let Some((name, desc, def)) = positional {
        s.push_str("Arguments:\n");
        if long {
            s.push_str(&format!("  [{}]\n          {}\n          \n          [default: {}]\n\n", name, desc, def));
        } else {
            s.push_str(&format!("  [{}]  {} [default: {}]\n", name, desc, def));
        }
    }
    s.push_str("Options:\n");
    for o in opts {
        s.push_str(&o.render(long));
    }
    // trailing help entry
    if long {
        s.push_str("  -h, --help\n          Print help (see a summary with '-h')\n");
    } else {
        s.push_str("  -h, --help\n          Print help (see more with '--help')\n");
    }
    // Remove trailing newline for parity
    if s.ends_with('\n') { s.pop(); }
    s
}

// -------- Option specification --------------------------------------------

#[derive(Clone)]
enum ArgKind {
    String,
    SockAddr,
    IpAddr,
    U16,
    U64,
    Size,
    Enum(&'static [&'static str]),
}

#[derive(Clone)]
struct OptSpec {
    long: &'static str,
    short: Option<char>,
    value_name: Option<&'static str>,
    #[allow(dead_code)]
    short_desc: &'static str,
    #[allow(dead_code)]
    default: Option<&'static str>,
    long_lines: &'static [&'static str],
    kind: ArgKind,
    takes_value: bool,
}

impl OptSpec {
    fn value(long: &'static str, short: Option<char>, vname: &'static str, desc: &'static str, default: Option<&'static str>,
             long_lines: &'static [&'static str], kind: ArgKind) -> Self {
        Self { long, short, value_name: Some(vname), short_desc: desc, default, long_lines, kind, takes_value: true }
    }
    fn flag(long: &'static str, desc: &'static str, long_lines: &'static [&'static str]) -> Self {
        Self { long, short: None, value_name: None, short_desc: desc, default: None, long_lines, kind: ArgKind::String, takes_value: false }
    }
    fn header(&self) -> String {
        // e.g. "      --listen <LISTEN>"  or "  -k, --key <KEY>"
        let mut h = String::new();
        match self.short {
            Some(c) => h.push_str(&format!("  -{}, {}", c, self.long)),
            None => h.push_str(&format!("      {}", self.long)),
        }
        if let Some(v) = self.value_name {
            h.push_str(&format!(" <{}>", v));
        }
        h
    }

    fn render(&self, long: bool) -> String {
        let mut s = String::new();
        s.push_str(&self.header());
        s.push('\n');
        if long {
            for (i, line) in self.long_lines.iter().enumerate() {
                if line.is_empty() {
                    // Indent then no trailing content for blank separator lines
                    s.push_str("          \n");
                    let _ = i;
                } else {
                    s.push_str(&format!("          {}\n", line));
                }
            }
            s.push('\n');
        } else {
            // short form: single-line description merging default
            let desc = self.short_desc;
            let inline_tail = match (&self.default, matches!(self.kind, ArgKind::Enum(_))) {
                (Some(d), _) => format!(" [default: {}]", d),
                (None, true) => {
                    if let ArgKind::Enum(vals) = &self.kind {
                        format!(" [possible values: {}]", vals.join(", "))
                    } else {
                        String::new()
                    }
                }
                _ => String::new(),
            };
            s.push_str(&format!("          {}{}\n", desc, inline_tail));
        }
        s
    }
}

// -------- help subcommand -------------------------------------------------

pub fn run_help(prog: &str, args: &[String]) -> ExitCode {
    // Mimic clap: `help [SUB]...`
    match args.first().map(String::as_str) {
        None => {
            println!("{}", top_help(prog));
            ExitCode::from(0)
        }
        Some("server") => {
            println!("{}", server_long_help(prog));
            ExitCode::from(0)
        }
        Some("client") => {
            println!("{}", client_long_help(prog));
            ExitCode::from(0)
        }
        Some("help") => {
            println!("{}", help_help());
            ExitCode::from(0)
        }
        Some(other) => {
            let mut out = String::new();
            out.push_str(&format!("error: unrecognized subcommand '{}'\n\n", other));
            // For "help <sub>" errors targeting unknown SUB, emit usage line
            // based on the previously named subcommand if present.
            if args.len() >= 2 {
                // The second arg: treat as sub-subcommand; emit usage for the
                // referenced parent. Follows clap's "help <cmd> <bad>" path.
                match args[0].as_str() {
                    "server" => out.push_str(&format!("Usage: {} server [OPTIONS]\n", prog)),
                    "client" => out.push_str(&format!("Usage: {} client [OPTIONS] [HOST]\n", prog)),
                    _ => out.push_str(&top_usage(prog)),
                }
            } else {
                out.push_str(&top_usage(prog));
            }
            out.push_str("\nFor more information, try '--help'.\n");
            eprint!("{}", out);
            ExitCode::from(2)
        }
    }
}

// -------- Argument parsing helpers ----------------------------------------

#[derive(Debug)]
struct UsageContext {
    used: Vec<String>, // as presented in usage line (e.g., "--keylog", "--initial-mtu <INITIAL_MTU>")
    has_positional: bool,
}

fn fmt_usage(prog: &str, sub: &str, ctx: &UsageContext) -> String {
    let mut u = format!("Usage: {} {}", prog, sub);
    if ctx.used.is_empty() {
        u.push_str(" [OPTIONS]");
    } else {
        for tok in &ctx.used {
            u.push(' ');
            u.push_str(tok);
        }
    }
    if ctx.has_positional {
        u.push_str(" [HOST]");
    }
    u.push('\n');
    u
}

fn err_unknown(prog: &str, sub: &str, arg: &str, ctx: &UsageContext, with_tip: bool) -> String {
    let mut s = String::new();
    s.push_str(&format!("error: unexpected argument '{}' found\n\n", arg));
    if with_tip {
        s.push_str(&format!("  tip: to pass '{}' as a value, use '-- {}'\n\n", arg, arg));
    }
    s.push_str(&fmt_usage(prog, sub, ctx));
    s.push_str("\nFor more information, try '--help'.\n");
    s
}

fn err_missing_value(opt_header: &str) -> String {
    format!(
        "error: a value is required for '{}' but none was supplied\n\nFor more information, try '--help'.\n",
        opt_header
    )
}

fn err_invalid_value(opt_header: &str, val: &str, msg: &str) -> String {
    let mut s = String::new();
    if msg.is_empty() {
        s.push_str(&format!("error: invalid value '{}' for '{}'\n\n", val, opt_header));
    } else {
        s.push_str(&format!(
            "error: invalid value '{}' for '{}': {}\n\n",
            val, opt_header, msg
        ));
    }
    s.push_str("For more information, try '--help'.\n");
    s
}

fn err_invalid_value_enum(opt_header: &str, val: &str, allowed: &[&str]) -> String {
    let mut s = String::new();
    s.push_str(&format!("error: invalid value '{}' for '{}'\n", val, opt_header));
    s.push_str(&format!("  [possible values: {}]\n\n", allowed.join(", ")));
    s.push_str("For more information, try '--help'.\n");
    s
}

fn parse_size(v: &str) -> Result<u64, String> {
    // Accept k, M, G, T suffixes (k=1024, M=1024^2, G=1024^3, T=1024^4)
    if v.is_empty() {
        return Err("cannot parse integer from empty string".to_string());
    }
    let (num_part, mult) = match v.chars().last().unwrap() {
        'k' => (&v[..v.len() - 1], 1024u64),
        'M' => (&v[..v.len() - 1], 1024u64 * 1024),
        'G' => (&v[..v.len() - 1], 1024u64 * 1024 * 1024),
        'T' => (&v[..v.len() - 1], 1024u64 * 1024 * 1024 * 1024),
        c if c.is_ascii_digit() => (v, 1u64),
        _ => return Err("invalid digit found in string".to_string()),
    };
    if num_part.is_empty() {
        return Err("cannot parse integer from empty string".to_string());
    }
    for c in num_part.chars() {
        if !c.is_ascii_digit() {
            return Err("invalid digit found in string".to_string());
        }
    }
    let base: u128 = num_part.parse::<u128>()
        .map_err(|_| "number too large to fit in target type".to_string())?;
    let val = base.checked_mul(mult as u128)
        .ok_or_else(|| "number too large to fit in target type".to_string())?;
    if val > u64::MAX as u128 {
        return Err("number too large to fit in target type".to_string());
    }
    Ok(val as u64)
}

fn parse_u64(v: &str) -> Result<u64, String> {
    if v.is_empty() { return Err("cannot parse integer from empty string".to_string()); }
    for c in v.chars() {
        if !c.is_ascii_digit() { return Err("invalid digit found in string".to_string()); }
    }
    v.parse::<u64>().map_err(|_| "number too large to fit in target type".to_string())
}

fn parse_u16_range(v: &str) -> Result<u16, String> {
    if v.is_empty() { return Err("cannot parse integer from empty string".to_string()); }
    for c in v.chars() {
        if !c.is_ascii_digit() { return Err("invalid digit found in string".to_string()); }
    }
    let n: u128 = v.parse::<u128>().map_err(|_| "number too large to fit in target type".to_string())?;
    if n > 65535 {
        return Err(format!("{} is not in 0..=65535", v));
    }
    Ok(n as u16)
}

fn parse_sock_addr(v: &str) -> Result<SocketAddr, String> {
    v.parse::<SocketAddr>().map_err(|_| "invalid socket address syntax".to_string())
}

fn parse_ip_addr(v: &str) -> Result<std::net::IpAddr, String> {
    v.parse::<std::net::IpAddr>().map_err(|_| "invalid IP address syntax".to_string())
}

fn validate_value(spec: &OptSpec, val: &str) -> Result<(), String> {
    match &spec.kind {
        ArgKind::String => Ok(()),
        ArgKind::SockAddr => parse_sock_addr(val).map(|_| ()),
        ArgKind::IpAddr => parse_ip_addr(val).map(|_| ()),
        ArgKind::U16 => parse_u16_range(val).map(|_| ()),
        ArgKind::U64 => parse_u64(val).map(|_| ()),
        ArgKind::Size => parse_size(val).map(|_| ()),
        ArgKind::Enum(vals) => {
            if vals.iter().any(|v| *v == val) { Ok(()) } else {
                Err(String::new())
            }
        }
    }
}

fn find_opt<'a>(specs: &'a [OptSpec], name: &str) -> Option<&'a OptSpec> {
    for s in specs {
        if s.long == name { return Some(s); }
        if let Some(c) = s.short {
            if name.len() == 2 && name.starts_with('-') && name.as_bytes()[1] as char == c {
                return Some(s);
            }
        }
    }
    None
}

fn usage_token(spec: &OptSpec) -> String {
    if let Some(v) = spec.value_name {
        format!("{} <{}>", spec.long, v)
    } else {
        spec.long.to_string()
    }
}

fn parse_positional_is_host(arg: &str) -> bool {
    !arg.starts_with('-')
}

// Parse arguments for a subcommand. Returns the remaining positional args and parsed values, or exits on error.
struct ParsedArgs {
    values: std::collections::HashMap<String, String>,
    flags: std::collections::HashSet<String>,
    positional: Vec<String>,
}

fn parse_args(prog: &str, sub: &str, specs: &[OptSpec], raw: &[String], accept_positional: bool) -> Result<ParsedArgs, (String, u8)> {
    let mut values = std::collections::HashMap::new();
    let mut flags = std::collections::HashSet::new();
    let mut positional: Vec<String> = Vec::new();
    let mut ctx = UsageContext { used: Vec::new(), has_positional: accept_positional };

    let mut i = 0;
    let mut after_double_dash = false;
    while i < raw.len() {
        let a = &raw[i];
        if after_double_dash {
            if accept_positional && positional.is_empty() {
                positional.push(a.clone());
                ctx.used.clear();
            } else {
                return Err((err_unknown(prog, sub, a, &ctx, false), 2));
            }
            i += 1;
            continue;
        }
        if a == "--" {
            after_double_dash = true;
            i += 1;
            continue;
        }
        if a == "-h" {
            return Err((match sub { "server" => server_short_help(prog), "client" => client_short_help(prog), _ => top_help(prog) }, 0));
        }
        if a == "--help" {
            return Err((match sub { "server" => server_long_help(prog), "client" => client_long_help(prog), _ => top_help(prog) }, 0));
        }
        // long option
        if let Some(rest) = a.strip_prefix("--") {
            if rest.is_empty() {
                // "--" alone handled above; won't reach here
            }
            let (name, value): (String, Option<String>) = if let Some(eq) = rest.find('=') {
                (format!("--{}", &rest[..eq]), Some(rest[eq + 1..].to_string()))
            } else {
                (format!("--{}", rest), None)
            };
            let spec = match find_opt(specs, &name) {
                Some(s) => s,
                None => return Err((err_unknown(prog, sub, a, &ctx, false), 2)),
            };
            if spec.takes_value {
                let val = match value {
                    Some(v) => v,
                    None => {
                        if i + 1 >= raw.len() {
                            let header = if let Some(v) = spec.value_name { format!("{} <{}>", spec.long, v) } else { spec.long.to_string() };
                            return Err((err_missing_value(&header), 2));
                        } else {
                            i += 1;
                            raw[i].clone()
                        }
                    }
                };
                let header = if let Some(v) = spec.value_name { format!("{} <{}>", spec.long, v) } else { spec.long.to_string() };
                if let Err(msg) = validate_value(spec, &val) {
                    if let ArgKind::Enum(allowed) = spec.kind {
                        return Err((err_invalid_value_enum(&header, &val, allowed), 2));
                    }
                    return Err((err_invalid_value(&header, &val, &msg), 2));
                }
                values.insert(spec.long.to_string(), val);
                ctx.used.push(usage_token(spec));
            } else {
                // Flag: no equals allowed
                if let Some(v) = value {
                    return Err((format!(
                        "error: unexpected value '{}' for '{}' found; no more were expected\n\nUsage: {} {} {}\n\nFor more information, try '--help'.\n",
                        v, spec.long, prog, sub, spec.long
                    ), 2));
                }
                flags.insert(spec.long.to_string());
                ctx.used.push(spec.long.to_string());
            }
            i += 1;
            continue;
        }
        // short option
        if a.starts_with('-') && a.len() >= 2 && a.as_bytes()[1] as char != '-' {
            let c = a.as_bytes()[1] as char;
            let spec = match find_opt(specs, &format!("-{}", c)) {
                Some(s) => s,
                None => return Err((err_unknown(prog, sub, a, &ctx, false), 2)),
            };
            if spec.takes_value {
                let attached = &a[2..];
                let val = if attached.is_empty() {
                    if i + 1 >= raw.len() {
                        let header = if let Some(v) = spec.value_name { format!("{} <{}>", spec.long, v) } else { spec.long.to_string() };
                        return Err((err_missing_value(&header), 2));
                    } else {
                        i += 1;
                        raw[i].clone()
                    }
                } else if let Some(s) = attached.strip_prefix('=') {
                    s.to_string()
                } else {
                    attached.to_string()
                };
                let header = if let Some(v) = spec.value_name { format!("{} <{}>", spec.long, v) } else { spec.long.to_string() };
                if let Err(msg) = validate_value(spec, &val) {
                    if let ArgKind::Enum(allowed) = spec.kind {
                        return Err((err_invalid_value_enum(&header, &val, allowed), 2));
                    }
                    return Err((err_invalid_value(&header, &val, &msg), 2));
                }
                values.insert(spec.long.to_string(), val);
                ctx.used.push(usage_token(spec));
            } else {
                flags.insert(spec.long.to_string());
                ctx.used.push(spec.long.to_string());
            }
            i += 1;
            continue;
        }
        // positional
        if parse_positional_is_host(a) {
            if accept_positional && positional.is_empty() {
                positional.push(a.clone());
                // clear used because positional terminates flag-chain in error usage.
                ctx.used.clear();
            } else {
                return Err((err_unknown(prog, sub, a, &ctx, false), 2));
            }
            i += 1;
            continue;
        }
        // starts with '-' but unmatched short
        let tip = accept_positional;
        return Err((err_unknown(prog, sub, a, &ctx, tip), 2));
    }

    // Required groups: --key and --cert must be provided together
    let has_key = values.contains_key("--key");
    let has_cert = values.contains_key("--cert");
    if has_key && !has_cert {
        return Err((format!(
            "error: the following required arguments were not provided:\n  --cert <CERT>\n\nUsage: {} {} --key <KEY> --cert <CERT>\n\nFor more information, try '--help'.\n",
            prog, sub
        ), 2));
    }
    if has_cert && !has_key {
        return Err((format!(
            "error: the following required arguments were not provided:\n  --key <KEY>\n\nUsage: {} {} --cert <CERT> --key <KEY>\n\nFor more information, try '--help'.\n",
            prog, sub
        ), 2));
    }

    Ok(ParsedArgs { values, flags, positional })
}

// -------- server / client runtime -----------------------------------------

pub fn run_server(prog: &str, args: &[String]) -> ExitCode {
    let specs = server_opts();
    let parsed = match parse_args(prog, "server", &specs, args, false) {
        Ok(p) => p,
        Err((msg, 0)) => { print!("{}", msg); println!(); return ExitCode::from(0); }
        Err((msg, code)) => { eprint!("{}", msg); return ExitCode::from(code); }
    };

    // Parse the interesting values.
    let send_buf = parsed
        .values
        .get("--send-buffer-size")
        .map(|s| parse_size(s).unwrap_or(0))
        .unwrap_or(2 * 1024 * 1024);
    let recv_buf = parsed
        .values
        .get("--recv-buffer-size")
        .map(|s| parse_size(s).unwrap_or(0))
        .unwrap_or(2 * 1024 * 1024);
    let listen: SocketAddr = parsed
        .values
        .get("--listen")
        .map(|s| s.parse().unwrap())
        .unwrap_or_else(|| "[::]:4433".parse().unwrap());

    // Validate key/cert files early (before buffer warnings in the original? Actually after).
    // Key/cert require reading; produce the expected error and exit.
    let maybe_key = parsed.values.get("--key").cloned();
    let maybe_cert = parsed.values.get("--cert").cloned();
    if let (Some(key), Some(_cert)) = (maybe_key, maybe_cert) {
        // Match the error format seen in the original binary.
        match std::fs::read(&key) {
            Ok(contents) => {
                let text = String::from_utf8_lossy(&contents);
                if !text.contains("-----BEGIN") {
                    logger::error("quinn_perf", "reading private key: no items found");
                    return ExitCode::from(1);
                }
            }
            Err(e) => {
                logger::error(
                    "quinn_perf",
                    &format!("reading private key: I/O error: {} (os error {})", e, e.raw_os_error().unwrap_or(0)),
                );
                return ExitCode::from(1);
            }
        }
    }

    let sock = try_bind_udp(listen);
    emit_buffer_warnings(send_buf, recv_buf, sock.as_ref());
    let _ = parsed.flags;
    logger::info("perf::server", &format!("listening on {}", listen));
    sleep_forever();
    ExitCode::from(0)
}

pub fn run_client(prog: &str, args: &[String]) -> ExitCode {
    let specs = client_opts();
    let parsed = match parse_args(prog, "client", &specs, args, true) {
        Ok(p) => p,
        Err((msg, 0)) => { print!("{}", msg); println!(); return ExitCode::from(0); }
        Err((msg, code)) => { eprint!("{}", msg); return ExitCode::from(code); }
    };
    let host_arg = parsed
        .positional
        .get(0)
        .cloned()
        .unwrap_or_else(|| "localhost:4433".to_string());

    let send_buf = parsed
        .values
        .get("--send-buffer-size")
        .map(|s| parse_size(s).unwrap_or(0))
        .unwrap_or(2 * 1024 * 1024);
    let recv_buf = parsed
        .values
        .get("--recv-buffer-size")
        .map(|s| parse_size(s).unwrap_or(0))
        .unwrap_or(2 * 1024 * 1024);

    // Validate MTU upper bound against supported range if specified > a few thousand.
    if let Some(v) = parsed.values.get("--max-udp-payload-size") {
        let n: u16 = v.parse().unwrap_or(0);
        if n > 65527 {
            logger::warn("perf", &format!("Unable to set desired send buffer size. Desired: {}, Actual: 425984", send_buf));
            logger::warn("perf", &format!("Unable to set desired recv buffer size. Desired: {}, Actual: 425984", recv_buf));
            logger::error("quinn_perf", "value exceeds supported bounds");
            return ExitCode::from(1);
        }
    }

    // Resolve host
    let (host_name, remote_addr) = match resolve_host(&host_arg) {
        Ok(v) => v,
        Err(_) => {
            logger::error("quinn_perf", "resolving host: invalid socket address");
            return ExitCode::from(1);
        }
    };

    let remote_addr = if let Some(ip) = parsed.values.get("--ip") {
        let ip: std::net::IpAddr = ip.parse().unwrap();
        crate::override_ip_addr(remote_addr, ip)
    } else { remote_addr };

    logger::info("perf::client", &format!("connecting to {} at {}", host_name, remote_addr));
    let local_addr: SocketAddr = parsed
        .values
        .get("--local-addr")
        .and_then(|s| s.parse().ok())
        .unwrap_or_else(|| match remote_addr {
            SocketAddr::V4(_) => "0.0.0.0:0".parse().unwrap(),
            SocketAddr::V6(_) => "[::]:0".parse().unwrap(),
        });
    logger::info("perf::client", &format!("local addr {}", local_addr));

    let sock = try_bind_udp(local_addr);
    emit_buffer_warnings(send_buf, recv_buf, sock.as_ref());

    // No real QUIC: we can't actually connect. Emulate the 30s connect timeout
    // behaviour observed from the original binary.
    std::thread::sleep(std::time::Duration::from_secs(30));
    logger::error("quinn_perf", "connecting: timed out");
    ExitCode::from(0)
}
